package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Real native workflows for the research release, including retained tiles and PDF restoration. */
public final class EightResearchSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());EightDefaults.initialize(store);store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();
        ui(()->{home.open("@settings");EightPCSettings settings=find(EightPCSettings.class);check(EightPCSettings.CATEGORIES.length==13&&EightPCSettings.CATEGORIES_81.length==9,"Historical category coverage");description(settings,"Use Windows 8.1 shell").performClick();settings.navigate("pcdevices/display");check(settings.location().equals("pcdevices/display")&&description(settings,"Open Display")!=null,"Nested display page");settings.goBack();check(settings.location().equals("pcdevices")&&settings.isShown(),"Settings back stays in category");});shot("eight5-settings");
        ui(()->{home.open("eight-desktop:taskbar");EightTaskbarProperties properties=find(EightTaskbarProperties.class);CheckBox previews=(CheckBox)description(properties,"Show thumbnail previews");check(previews!=null,"Taskbar property sheet");previews.performClick();check(store.prefs.getBoolean("taskbar_previews",true),"Pending taskbar edits do not apply immediately");description(properties,"Taskbar properties Apply").performClick();check(!store.prefs.getBoolean("taskbar_previews",true),"Apply commits taskbar edits");});shot("eight5-taskbar-properties");
        ui(()->{store.prefs.edit().putLong("feed_updated",System.currentTimeMillis()).putLong("feed_expires",System.currentTimeMillis()+600000).putString("feed_items","[{\"title\":\"A cached headline from the native test feed\",\"url\":\"https://example.com/a\"}]").commit();home.open("@start");EightStartScreen start=find(EightStartScreen.class);start.data.pin("@news");start.appearanceChanged();check(start.liveTiles.snapshot("@news",System.currentTimeMillis())!=null,"Fresh news provider");View tile=description(start,"News, Medium Start tile"),parent=(View)tile.getParent();start.refreshLiveTiles();check(tile.getParent()==parent&&description(start,"News, Medium Start tile")==tile,"Provider update preserves the actual tile view");start.liveTiles.toggle("@news");check(start.liveTiles.snapshot("@news",System.currentTimeMillis())==null,"Per-tile live off");start.liveTiles.toggle("@news");store.prefs.edit().putLong("feed_expires",1).commit();check(start.liveTiles.snapshot("@news",System.currentTimeMillis())==null,"Expired headline removed");store.prefs.edit().putLong("feed_expires",System.currentTimeMillis()+600000).commit();start.refreshLiveTiles();});shot("eight5-live-tiles");
        ui(()->{check(EightReadingList.add(store,"https://example.com/saved","Saved reading fixture"),"Save reading item");home.openEightTile("@readinglist");EightReadingList list=find(EightReadingList.class);check(description(list,"Read saved article: Saved reading fixture")!=null,"Reading List has real persisted item");list.mark("https://example.com/saved",true,false);check(EightReadingList.items(store).optJSONObject(0).optBoolean("read"),"Reading state persisted");try{DesktopBackup.Plan backup=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(backup.values.containsKey(EightReadingList.KEY),"Reading List travels with backup");}catch(JSONException e){throw new RuntimeException(e);}});shot("eight5-reading-list");
        File folder=new File(getTargetContext().getFilesDir(),"eight");folder.mkdirs();File pdf=new File(folder,"research-test.pdf");PdfDocument document=new PdfDocument();try{for(int i=1;i<=2;i++){PdfDocument.Page page=document.startPage(new PdfDocument.PageInfo.Builder(600,800,i).create());Paint paint=new Paint();paint.setColor(Color.BLACK);paint.setTextSize(28);page.getCanvas().drawText("Reader native fixture · page "+i,40,100,paint);document.finishPage(page);}try(OutputStream out=new FileOutputStream(pdf)){document.writeTo(out);}}finally{document.close();}Uri uri=androidx.core.content.FileProvider.getUriForFile(getTargetContext(),getTargetContext().getPackageName()+".eight-files",pdf);
        ui(()->home.openPdf(uri));awaitReader("Page 1 of 2");ui(()->description(find(EightReader.class),"Reader Next").performClick());awaitReader("Page 2 of 2");shot("eight5-reader");ui(()->{EightReader reader=find(EightReader.class);View parent=reader;while(!(parent instanceof DesktopWindow))parent=(View)parent.getParent();((DesktopWindow)parent).closeWindow();home.open("@reader");});awaitReader("Page 2 of 2");
        ui(()->{home.open("@wordpad");EightWordPad pad=find(EightWordPad.class);pad.editor.setText("Rich text fixture");pad.editor.setSelection(0,4);pad.command("Bold");check(store.prefs.getString("eight_wordpad_html","").contains("<b>Rich</b>"),"WordPad formatting persists");home.open("@characters");EightCharacterMap map=find(EightCharacterMap.class);check(map.grid.getChildCount()>0,"Supported characters available");map.grid.getChildAt(0).performClick();check(map.selection.length()>0,"Character selection works");home.open("@paint");check(find(EightPaint.class)!=null,"Paint canvas opens");});shot("eight5-paint");
        ui(()->{home.openEightTile("@alarms");EightAlarms alarms=find(EightAlarms.class);alarms.tab="Stopwatch";alarms.render();description(alarms,"Alarms Start").performClick();check(alarms.running(),"Stopwatch starts");description(alarms,"Alarms Pause").performClick();check(!alarms.running(),"Stopwatch pauses");home.openEightTile("@soundrecorder");check(find(EightSoundRecorder.class).recorder==null,"Opening Recorder never starts the microphone");check(((android.graphics.drawable.ColorDrawable)find(EightSoundRecorder.class).getBackground()).getColor()==0xff9c241f,"Owned recorder keeps its intended surface contrast");});shot("eight5-recorder");
        ui(()->{home.open("@mobility");check(description(find(EightMobilityCenter.class),"Mobility Center media volume")!=null,"Mobility Center uses actual device control");home.openEightTile("@help");EightHelpTips help=find(EightHelpTips.class);help.topic("files");check(description(help,"Help topic files")!=null,"Contextual tips replay");});shot("eight5-help");
        ui(()->{home.open("@desktop");home.open("@computer");VistaExplorer explorer=visible(root,VistaExplorer.class);check(explorer!=null&&description(explorer,"Computer ribbon tab")!=null&&description(explorer,"Home ribbon tab")==null,"Computer has a contextual ribbon");home.open("@recycle");check(description(find(RecyclePanel.class),"Sort Recycle Bin by Item type")!=null,"Recycle Bin item type column");});shot("eight5-recycle");
        ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));SystemClock.sleep(800);ui(()->home.open("@mobility"));shot("eight5-mobility-landscape");
        result.putString("stream","PASS: nested settings and Back; pending Taskbar Apply; real provider expiry and retained tile identity; live toggle; Reading List backup/read-state; actual two-page PDF rendering and reopen; rich text formatting; character selection; Paint; stopwatch; recorder microphone privacy; Mobility Center; contextual help; Computer ribbon and Recycle Bin type column; portrait/landscape\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("eight5-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));finish(Activity.RESULT_CANCELED,result);}}
    void awaitReader(String value)throws Exception{long until=SystemClock.uptimeMillis()+15000;boolean[] ready={false};while(SystemClock.uptimeMillis()<until){ui(()->{EightReader r=find(EightReader.class);ready[0]=r!=null&&r.status.getText().toString().startsWith(value)&&r.image.getDrawable()!=null&&("PDF "+value.toLowerCase(Locale.ROOT)).equals(r.image.getContentDescription());});if(ready[0])return;SystemClock.sleep(100);}throw new AssertionError("PDF did not render "+value);}
    void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(25,TimeUnit.SECONDS);waitForIdleSync();}
    void check(boolean value,String label){if(!value)throw new AssertionError(label);}
    <T extends View>T find(Class<T> c){return EightSmoke.find(root,c);}static View description(View root,String value){return EightSmoke.description(root,value);}
    static <T extends View>T visible(View root,Class<T> c){if(c.isInstance(root)&&root.isShown())return c.cast(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){T found=visible(((ViewGroup)root).getChildAt(i),c);if(found!=null)return found;}return null;}
    void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(150);Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap==null){bitmap=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);Bitmap target=bitmap;ui(()->root.draw(new Canvas(target)));}try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
}
